import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.DC2anBTf.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"en/changelog.md","filePath":"en/changelog.md","lastUpdated":1793595620000}'),r={name:"en/changelog.md"};function n(d,e,s,l,c,g){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>This page stays in sync with the root <a href="https://github.com/MengXi-Studio/unix-architecture/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a>.</p><h2 id="_1-1-0-2026-11-02" tabindex="-1">[1.1.0] - 2026-11-02 <a class="header-anchor" href="#_1-1-0-2026-11-02" aria-label="Permalink to &quot;[1.1.0] - 2026-11-02&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>UI component library integration</strong> (<code>uni_modules/m-ui-x</code> v0.1.0): 11 base components wired in with zero-registration easycom; theming via <code>$m-*</code> variables defined in the root <code>uni.scss</code> overridden at compile time (<code>@import</code> of vars.scss forbidden, preventing sass circular imports).</li><li><strong>Page consumption replacement</strong>: login / home page buttons replaced with <code>m-button</code> (loading state bound to useLoading, danger-plain-hairline semantic forms).</li><li><strong>ux-router 0.8.2 <code>backFallback</code> integration</strong>: when the page stack is too shallow for back(), it falls back to relaunching home (through the full guard chain).</li><li><strong>Documentation site</strong>: VitePress usage docs (this site), deployed on GitHub Pages.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Mandatory migration ux-pinia 0.1.0 → 0.2.0</strong> (the plugin&#39;s setup-style API removed): stores rewritten as class-style <code>UserStore extends PiniaStoreBase</code> (state wrapped in <code>reactive&lt;T&gt;</code>, actions as methods, <code>bindState</code> in the constructor); <code>storeToRefs</code> / <code>.value</code> access replaced by direct <code>store.state.field</code> reads.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Release packaging fixes</strong>: exporting string constants from UTS plugin entries generated invalid JS in the 5.34 release pipeline (9 unused constants de-exported); app-android release builds do not follow <code>export type ... from</code> forwarding chains (domain types consolidated into single types.uts files); Android cloud-packaging Kotlin compilation fixes (explicit generics, explicit guardRoute arguments, m-loading avoiding 5.34 generator defects).</li></ul><h3 id="verified" tabindex="-1">Verified <a class="header-anchor" href="#verified" aria-label="Permalink to &quot;Verified&quot;">​</a></h3><ul><li>Web login loop E2E; Android cloud-packaging compilation passed (Kotlin pipeline).</li><li>Android cloud-packaging artifact (APK): <code>__UNI__FDA7014</code> — <a href="https://mp-b8b8347a-48e9-434d-8302-3e9d99c2cb01.cdn.bspapp.com/cloudstorage/app-build-pkg/1793535799767-__UNI__FDA7014_1793535789282.apk" target="_blank" rel="noreferrer">https://mp-b8b8347a-48e9-434d-8302-3e9d99c2cb01.cdn.bspapp.com/cloudstorage/app-build-pkg/1793535799767-__UNI__FDA7014_1793535789282.apk</a> (direct uniCloud storage link, time-limited; if expired, re-package via HBuilderX cloud packaging).</li></ul><h2 id="_1-0-0-2026-10-21" tabindex="-1">[1.0.0] - 2026-10-21 <a class="header-anchor" href="#_1-0-0-2026-10-21" aria-label="Permalink to &quot;[1.0.0] - 2026-10-21&quot;">​</a></h2><p>The engineering architecture built from zero to its first stable form: api / stores / router / utils / pages fully layered, verified end to end on Web. Includes the layered skeleton, network layer wrapper (dual interceptors), auth system (in-memory cache + ensureAuthReady), global guards (whitelist + cold-start re-run + InterceptorPlugin fallback), type organization system, ux-utils integration, and the AI collaboration rules system (.trae).</p><p>Full history in the repository <a href="https://github.com/MengXi-Studio/unix-architecture/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a>.</p>',14)])])}const p=a(r,[["render",n]]);export{u as __pageData,p as default};
